INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(16898077, 'Flying Fortress SKY FIRE', '巨人轰炸机·大空袭式', 'ジャイアント・ボマー・エアレイド', 'Effect Monster', 'Machine', 'WIND', 8, 3000, 2500, '这张卡不能通常召唤。「召唤反应机·大式」的效果才能特殊召唤。1回合1次，可以把1张手卡送去墓地让对方场上存在的1张卡破坏。此外，对方回合1次，可以从下面效果选择1个发动。 ●对方对怪兽的召唤、特殊召唤成功时才能发动。把那些怪兽破坏，给与对方基本分800分伤害。 ●对方把卡盖放时才能发动。把那些卡破坏，给与对方基本分800分伤害。'),
(84834865, 'Flying Kamakiri #1', '蜻蜓', 'ドラゴンフライ', 'Effect Monster', 'Insect', 'WIND', 4, 1400, 900, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只攻击力1500以下的风属性怪兽在自己场上表侧攻击表示特殊召唤。'),
(3134241, 'Flying Kamakiri #2', '飞螳螂', 'フライングマンティス', 'Normal Monster', 'Insect', 'WIND', 4, 1500, 800, '拥有飞行能力的螳螂，非常喜欢吃昆虫。'),
(95784714, 'Flying Mary, the Wandering Ghost Ship', '彷徨幽灵船 飞翔玛丽号', '彷徨える幽霊船', 'Link Monster', 'Zombie', 'WATER', NULL, NULL, NULL, '不死族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：以自己的墓地·除外状态的1只5星以上的不死族怪兽为对象才能发动。这张卡当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置，作为对象的怪兽特殊召唤。 ②：这张卡是当作永续魔法卡使用的场合，以自己场上1只5星以上的不死族怪兽为对象才能发动。持有那只怪兽的攻击力以下的攻击力的对方场上1只怪兽破坏。'),
(88875132, 'Flying Pegasus Railroad Stampede', '爆走轨道飞翔天马', '爆走軌道フライング・ペガサス', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以「爆走轨道 冲天飞马」以外的自己墓地1只机械族·地属性怪兽为对象才能发动。那只怪兽效果无效守备表示特殊召唤。 ②：以自己场上1只其他的表侧表示怪兽为对象才能发动（这个效果发动的回合，自己不用超量怪兽不能攻击宣言）。那只怪兽和这张卡之内的1只的等级变成和另1只的等级相同。'),
(5628232, 'Flying Penguin', '飞天企鹅', 'トビペンギン', 'Normal Monster', 'Aqua', 'WATER', 4, 1200, 1000, '用看似耳朵一般的头上羽翼在空中飞，很珍奇的企鹅。'),
(33314479, 'Flying Red Carp', '飞鲤', '飛鯉', 'Effect Monster', 'Fish', 'WATER', 4, 500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1只水属性怪兽才能发动。这张卡的攻击力上升500。这个效果在对方回合也能发动。 ②：这张卡战斗破坏对方怪兽时，把这张卡解放才能发动。从手卡·卡组把1只鱼族·海龙族·水族怪兽特殊召唤。'),
(97697678, 'Flying Saucer Muusik''i', '圆盘 姆斯基型', '円盤ムスキー', 'Effect Monster', 'Machine', 'LIGHT', 5, 1000, 2000, '只要这张卡在场上表侧表示存在，可以代替自己的抽卡阶段通常的抽卡，从卡组选择1张名字带有「外星」的卡加入手卡。'),
(72386290, 'Focused Aquamirror', '仪水镜之集光', '儀水鏡の集光', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从卡组把1只「遗式」怪兽加入手卡。 ②：自己场上有水属性仪式怪兽存在的场合，自己·对方的结束阶段，把墓地的这张卡除外才能发动。从自己的卡组·墓地选「仪水镜的集光」以外的1张「仪水镜」魔法·陷阱卡在自己场上盖放。'),
(63741331, 'Fog Control', '雾气操控', 'フォッグ・コントロール', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己表侧表示存在的1只名字带有「云魔物」的怪兽作为祭品，给场上表侧表示存在的1只怪兽放置3个雾指示物。'),
(6614221, 'Fog King', '雾之王', '霧の王', 'Effect Monster', 'Spellcaster', 'WATER', 7, NULL, NULL, '这张卡召唤的场合，可以用1只祭品或者不用祭品作召唤。这张卡的攻击力变成祭品召唤时作为祭品的怪兽的原本攻击力合计数值。只要这张卡在场上表侧表示存在，任何形式的祭品都不能进行。'),
(300302065, 'Fog Warning', NULL, NULL, 'Skill Card', 'Adrian Gecko', NULL, NULL, NULL, NULL, NULL),
(15001940, 'Foie Glasya de Nouvelles', '肥肝之佛格雷希亚・饿魔新飨', 'フォアグラシャ・ド・ヌーベルズ', 'Ritual Effect Monster', 'Warrior', 'DARK', 4, 1600, 1850, '「食谱」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以自己·对方的墓地的卡合计最多3张为对象才能发动。那些卡回到持有者卡组。 ②：场上的怪兽成为攻击·效果的对象时才能发动。自己场上1只「新式魔厨」怪兽和自己·对方场上1只攻击表示怪兽解放，从手卡·卡组把1只5·6星的「新式魔厨」仪式怪兽特殊召唤。'),
(66023650, 'Folgo, Justice Fur Hire', '空牙团之大义 风吼雷', '空牙団の大義 フォルゴ', 'Link Monster', 'Beast', 'DARK', NULL, 2400, NULL, '种族不同的怪兽3只 这张卡不能作为连接素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。和那3只作为连接素材的怪兽不同种族的1只「空牙团」怪兽从卡组守备表示特殊召唤。 ②：对方场上的卡被战斗·效果破坏的场合才能发动。自己从卡组抽1张。自己场上的「空牙团」怪兽是3种类以上的场合，再让自己从卡组抽2张。'),
(98252586, 'Follow Wind', '随风翼', 'フォロー・ウィンド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '鸟兽族怪兽可以装备。装备怪兽的攻击力·守备力上升300。'),
(42776855, 'Follow Wing', '追赶之翼', '追走の翼', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以自己场上1只同调怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，作为对象的怪兽不会被战斗以及对方的效果破坏。 ②：作为对象的怪兽和5星以上的对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏。作为对象的怪兽的攻击力直到回合结束时上升这个效果破坏的怪兽的原本攻击力数值。 ③：作为对象的怪兽从场上离开的场合这张卡破坏。'),
(63175639, 'Fool of Prophecy', '魔导化士 马特', '魔導化士 マット', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1600, 900, '1回合1次，可以从卡组把1张名字带有「魔导书」的魔法卡送去墓地。这个效果发动的回合的结束阶段时，自己墓地的名字带有「魔导书」的魔法卡是5种类以上的场合，可以通过把这张卡解放，从卡组把1只魔法师族·暗属性·5星以上的怪兽特殊召唤。'),
(81439173, 'Foolish Burial', '愚蠢埋葬', 'おろかな埋葬', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只怪兽送去墓地。'),
(35726888, 'Foolish Burial Goods', '愚蠢副葬', 'おろかな副葬', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张魔法·陷阱卡送去墓地。'),
(88369727, 'Foolish Return', '愚蠢的转生', 'おろかな転生', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择对方墓地存在的1张卡发动。选择的卡回到卡组。'),
(83778600, 'Foolish Revival', '错误复活', 'ミス・リバイブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方墓地1只怪兽才能发动。选择的怪兽在对方场上表侧守备表示特殊召唤。'),
(3211439, 'Forbidden Apocrypha', '禁断的异本', '禁断の異本', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：宣言1个怪兽卡的种类（融合·同调·超量）才能发动。宣言的种类的怪兽在场上有2只以上表侧表示存在的场合，双方玩家必须把场上的那个种类的怪兽全部送去墓地。'),
(28429121, 'Forbidden Arts of the Gishki', '咒仪世传禁断秘术', 'リチュアに伝わりし禁断の秘術', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '名字带有「遗式」的仪式怪兽的降临必需。必须从自己场上以及对方场上把直到变成和仪式召唤的怪兽相同等级为止的表侧表示存在的怪兽解放。这个效果仪式召唤的怪兽的攻击力变成一半。这张卡发动的回合，自己不能进行战斗阶段。'),
(25789292, 'Forbidden Chalice', '禁忌的圣杯', '禁じられた聖杯', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时攻击力上升400，效果无效化。'),
(98829635, 'Forbidden Crown', '禁忌的圣冠', '禁じられた聖冠', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，不能对应这张卡的发动让怪兽的效果发动。 ①：选场上1只表侧表示怪兽，直到回合结束时以下效果适用。 ●效果无效化。 ●不能攻击。 ●不会被战斗·效果破坏。 ●不受自身以外的卡发动的效果影响。 ●不能解放。 ●不能作为融合·同调·超量·连接召唤的素材。'),
(300302030, 'Forbidden Cyber Style Technique', NULL, NULL, 'Skill Card', 'Zane Truesdal', NULL, NULL, NULL, NULL, NULL),
(10833828, 'Forbidden Dark Contract with the Swamp King', '魔神王的禁断契约书', '魔神王の禁断契約書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段才能发动。从手卡把1只「DDD」怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：1回合1次，自己主要阶段才能发动。包含用这张卡的①的效果特殊召唤的怪兽的自己的手卡·场上的怪兽作为融合素材，把1只恶魔族融合怪兽融合召唤。 ③：自己准备阶段发动。自己受到2000伤害。'),
(96864811, 'Forbidden Dress', '禁忌的圣衣', '禁じられた聖衣', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽攻击力下降600，不会被效果破坏，双方不能把那只怪兽作为效果的对象。'),
(24299458, 'Forbidden Droplet', '禁忌的一滴', '禁じられた一滴', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，对方不能对应这张卡的发动把原本种类（怪兽·魔法·陷阱）和为这张卡发动而送去墓地的卡相同的卡的效果发动。 ①：从自己的手卡·场上把其他卡任意数量送去墓地才能发动。选那个数量的对方场上的效果怪兽。那些怪兽直到回合结束时攻击力变成一半，效果无效化。'),
(27243130, 'Forbidden Lance', '禁忌的圣枪', '禁じられた聖槍', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时攻击力下降800，不受其他的魔法·陷阱卡的效果影响。'),
(12157563, 'Forbidden Ritual Art', '禁断仪式术', '禁断儀式術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己墓地的怪兽除外，从自己墓地把1只仪式怪兽仪式召唤。这个效果特殊召唤的怪兽在结束阶段破坏。 ②：把墓地的这张卡除外才能发动。这个回合，自己仪式召唤的场合只有1次，自己墓地的仪式怪兽也能作为解放的代替而除外。'),
(54773234, 'Forbidden Scripture', '禁忌的圣典', '禁じられた聖典', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：双方怪兽进行战斗的伤害计算时才能发动。直到伤害步骤结束时，这张卡以外的场上的卡的效果无效化，那次战斗的伤害计算用原本的攻击力·守备力进行。'),
(49033797, 'Forbidden Trapezohedron', '禁断的偏方面体', '禁断のトラペゾヘドロン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「禁断的偏方面体」在1回合只能发动1张。 ①：自己场上的融合·同调·超量怪兽只有那之内2种类的场合，那个组合的以下效果适用。 ●融合·同调怪兽：从额外卡组把1只「外神」超量怪兽特殊召唤，把这张卡在下面重叠作为超量素材。 ●同调·超量怪兽：从额外卡组把1只「旧神」融合怪兽特殊召唤。 ●超量·融合怪兽：从额外卡组把1只「古神」同调怪兽特殊召唤。'),
(40583194, 'Force Resonator', '强要共鸣者', 'フォース・リゾネーター', 'Tuner Monster', 'Fiend', 'WATER', 2, 500, 500, '把自己场上表侧表示存在的这张卡送去墓地，选择自己场上表侧表示存在的1只怪兽发动。这个回合，选择的怪兽攻击的场合，对方直到伤害步骤结束时不能把以怪兽为对象的魔法·陷阱·效果怪兽的效果发动。'),
(43340443, 'Forced Back', '反冲', 'キックバック', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '怪兽的召唤·反转召唤无效，那只怪兽回到持有者手卡。'),
(97806240, 'Forced Ceasefire', '强引的安全协定', '強引な安全協定', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡。这个回合的结束阶段前，不能发动陷阱卡。'),
(74923978, 'Forced Requisition', '强制接收', '強制接収', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己丢弃手卡时才能发动。那之后每次自己的手卡丢弃，对方选择相同数量的手卡丢弃。'),
(87430998, 'Forest', '森', '森', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部昆虫族·兽族·植物族·兽战士族的怪兽攻击力·守备力上升200。'),
(91228233, 'Forest of Lost Flowers', '迷花之森', '迷い花の森', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：有「星空蝶」装备的自己怪兽不受对方发动的效果影响。 ②：1回合1次，自己的「勇者衍生物」战斗破坏怪兽时才能发动。自己从卡组抽1张。 ③：这张卡的②的效果发动的回合的自己主要阶段才能发动1次。从自己的卡组·墓地选「迷幻花之森」以外的1张有「勇者衍生物」的衍生物名记述的场地魔法卡加入手卡。'),
(27104921, 'Forge a New Future', '命运的囚人', '運命の囚人', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：连接4怪兽连接召唤的场合才能发动1次。给这张卡放置1个指示物（最多3个）。那之后，可以让这张卡的指示物数量的以下效果适用。 ●1个：宣言1个卡名。这个回合，原本卡名和宣言的卡相同的卡的效果无效化。 ●2个：从自己墓地选1只4星以下的怪兽特殊召唤。 ●3个：这张卡送去墓地，从额外卡组把1只连接4怪兽特殊召唤。'),
(87765315, 'Forge of the True Dracos', '真龙的觉醒', '真竜の目覚め', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：「龙魔王」怪兽以及除灵摆怪兽以外的「龙剑士」怪兽在场上存在的场合才能发动。双方场上的卡全部回到持有者卡组。那之后，可以从卡组把1只「龙剑士」怪兽或者「龙魔王」怪兽无视召唤条件特殊召唤。'),
(300302066, 'Forged Steel', NULL, NULL, 'Skill Card', 'Nightshroud', NULL, NULL, NULL, NULL, NULL),
(43889633, 'Forgotten Temple of the Deep', '忘却的海底神殿', '忘却の海底神殿', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，这张卡的卡名当作「海」使用。1回合1次，可以选择自己场上表侧表示存在的1只4星以下的鱼族·海龙族·水族怪兽从游戏中除外。这个效果除外的怪兽在自己的结束阶段时在场上特殊召唤。'),
(84536654, 'Form Change', '形态变换', 'フォーム・チェンジ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「英雄」融合怪兽为对象才能发动。那只怪兽回到额外卡组，和那只怪兽的原本等级相同等级而卡名不同的1只「假面英雄」怪兽当作「假面变化」的特殊召唤从额外卡组特殊召唤。'),
(26931058, 'Formation Union', '同盟编队', 'フォーメーション・ユニオン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从下面效果选择1个发动： ●选择自己场上表侧表示存在的1只同盟怪兽，给自己场上表侧表示存在的可以装备的怪兽装备。 ●把自己场上存在的1只当作装备卡使用的同盟怪兽的装备解除，在自己场上表侧攻击表示特殊召唤。'),
(50366775, 'Formud Skipper', '格式弹涂鱼', 'フォーマッド・スキッパー', 'Effect Monster', 'Cyberse', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。额外卡组1只连接怪兽给对方观看。这个回合连接召唤的场合，这张卡可以当作和给人观看的怪兽相同的卡名·种族·属性的素材使用。 ②：这张卡作为连接素材送去墓地的场合才能发动。从卡组把1只5星以上的电子界族怪兽加入手卡。'),
(50091196, 'Formula Synchron', '方程式同步士', 'フォーミュラ・シンクロン', 'Synchro Tuner Monster', 'Machine', 'LIGHT', 2, 200, 1500, '调整＋调整以外的怪兽1只 ①：这张卡同调召唤时才能发动。自己抽1张。 ②：对方主要阶段才能发动（同一连锁上最多1次）。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(11493868, 'Fortissimo', '极强音', 'フォルテッシモ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以自己场上1只「幻奏」怪兽为对象才能把这个效果发动。那只怪兽的攻击力直到下次的自己准备阶段上升800。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。「幻奏」融合怪兽卡决定的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(86997073, 'Fortissimo the Mobile Fortress', '机动要塞 极强音', '機動要塞フォルテシモ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '1回合1次，可以从自己手卡把1只名字带有「机皇兵」的怪兽在自己场上特殊召唤。'),
(66288028, 'Fortress Warrior', '重型战士', 'マッシブ・ウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 2, 600, 1200, '这张卡的战斗发生的对自己的战斗伤害变成0。这张卡1回合只有1次不会被战斗破坏。'),
(62337487, 'Fortress Whale', '要塞鲸', '要塞クジラ', 'Ritual Monster', 'Fish', 'WATER', 7, 2350, 2150, '借由「要塞鲸的誓言」降临。必须从场上或者手札，牺牲奉献等级合计为7个以上的卡。'),
(77454922, 'Fortress Whale''s Oath', '要塞鲸的誓言', '要塞クジラの誓い', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「要塞鲸」的降临必要。必须从场上或者手札，牺牲奉献等级合计为7个以上的卡。'),
(39299733, 'Fortune Chariot', '命运之战车', '運命の戦車', 'Union Effect Monster', 'Fairy', 'WIND', 6, 1000, 2000, '这个卡名在规则上也当作「女武神」卡使用。 ①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只天使族怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：装备怪兽可以直接攻击。那次直接攻击给与对方的战斗伤害变成一半。'),
(31683874, 'Fortune Fairy Ann', '占卜魔女 小暗', '占い魔女 アンちゃん', 'Effect Monster', 'Spellcaster', 'DARK', 5, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合才能发动。从卡组把1只魔法师族怪兽除外。'),
(68078978, 'Fortune Fairy Chee', '占卜魔女 小地', '占い魔女 チーちゃん', 'Effect Monster', 'Spellcaster', 'EARTH', 6, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合才能发动。双方玩家各自从卡组抽1张。'),
(32305461, 'Fortune Fairy En', '占卜魔女 小炎', '占い魔女 エンちゃん', 'Effect Monster', 'Spellcaster', 'FIRE', 2, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合，以对方场上盖放的1张卡为对象才能发动。那张卡破坏。'),
(6311717, 'Fortune Fairy Hikari', '占卜魔女 小光', '占い魔女 ヒカリちゃん', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合，以自己场上1只怪兽为对象才能发动。那只怪兽送去墓地，从卡组把1只魔法师族·1星怪兽特殊召唤。'),
(79890560, 'Fortune Fairy Hu', '占卜魔女 小风', '占い魔女 フウちゃん', 'Effect Monster', 'Spellcaster', 'WIND', 3, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合，以除外的1只自己的魔法师族怪兽为对象才能发动。那只怪兽加入手卡。'),
(5298175, 'Fortune Fairy Swee', '占卜魔女 小水', '占い魔女 スィーちゃん', 'Effect Monster', 'Spellcaster', 'WATER', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡从手卡的特殊召唤成功的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽直到下次的自己回合的准备阶段除外。'),
(27895597, 'Fortune Lady Calling', '命运女郎呼召', 'フォーチュンレディ・コーリング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「命运女郎」怪兽存在的场合才能发动。同名卡不在自己场上存在的1只「命运女郎」怪兽从卡组特殊召唤。这张卡的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。'),
(55586621, 'Fortune Lady Dark', '命运女郎·达琪', 'フォーチュンレディ・ダルキー', 'Effect Monster', 'Spellcaster', 'DARK', 5, -1, -1, '这张卡的攻击力·守备力变成这张卡的等级×400的数值。自己的准备阶段时，这张卡的等级上升1星（等级最多12星）。只要这张卡在自己场上表侧表示存在，自己场上表侧表示存在的名字带有「命运女郎」的怪兽战斗破坏对方怪兽送去墓地时，可以选择自己墓地存在的1只名字带有「命运女郎」的怪兽特殊召唤。'),
(82971335, 'Fortune Lady Earth', '命运女郎·厄希', 'フォーチュンレディ・アーシー', 'Effect Monster', 'Spellcaster', 'EARTH', 6, -1, -1, '这张卡的攻击力·守备力变成这张卡的等级×400的数值。自己的准备阶段时，这张卡的等级上升1星（等级最多12星）。这张卡的等级上升时，给与对方基本分400分伤害。'),
(70252926, 'Fortune Lady Every', '命运女郎·埃芙莉', 'フォーチュンレディ・エヴァリー', 'Synchro Monster', 'Spellcaster', 'LIGHT', 7, -1, -1, '调整＋调整以外的魔法师族怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力·守备力变成这张卡的等级×400。 ②：自己准备阶段发动。这张卡的等级上升1星（最多到12星）。那之后，可以选对方场上1只表侧表示怪兽除外。 ③：对方结束阶段有这张卡在墓地存在的场合，从自己墓地把这张卡以外的1只魔法师族怪兽除外才能发动。这张卡特殊召唤。'),
(71870152, 'Fortune Lady Fire', '命运女郎·菲莉', 'フォーチュンレディ・ファイリー', 'Effect Monster', 'Spellcaster', 'FIRE', 2, -1, -1, '这张卡的攻击力·守备力变成这张卡的等级×200的数值。自己的准备阶段时，这张卡的等级上升1星（等级最多12星）。这张卡用名字带有「命运女郎」的卡的效果表侧攻击表示特殊召唤成功时，把对方场上表侧表示存在的1只怪兽破坏，给与对方基本分破坏怪兽的攻击力数值的伤害。'),
(34471458, 'Fortune Lady Light', '命运女郎·莱蒂', 'フォーチュンレディ・ライティー', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, -1, -1, '①：这张卡的攻击力·守备力变成这张卡的等级×200。 ②：自己准备阶段发动。这张卡的等级上升1星（最多到12星）。 ③：表侧表示的这张卡因效果从场上离开时才能发动。从卡组把1只「命运女郎」怪兽特殊召唤。'),
(57869175, 'Fortune Lady Past', '命运女郎·帕丝蒂', 'フォーチュンレディ・パスティー', 'Tuner Monster', 'Spellcaster', 'DARK', 1, -1, -1, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力·守备力变成这张卡的等级×200。 ②：自己准备阶段发动。这张卡的等级上升1星（最多到12星）。 ③：以自己场上1只「命运女郎」怪兽为对象才能发动。那只怪兽以外的自己的手卡·场上·墓地的魔法师族怪兽任意数量除外，直到回合结束时作为对象的怪兽的等级上升或者下降除外的怪兽数量的数值。'),
(84218527, 'Fortune Lady Rewind', '命运女郎倒回', 'フォーチュンレディ・リワインド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以除外的自己的「命运女郎」怪兽任意数量为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者卡组。'),
(29088922, 'Fortune Lady Water', '命运女郎·沃特莉', 'フォーチュンレディ・ウォーテリー', 'Effect Monster', 'Spellcaster', 'WATER', 4, -1, -1, '①：这张卡的攻击力·守备力变成这张卡的等级×300。 ②：自己准备阶段发动。这张卡的等级上升1星（最多到12星）。 ③：自己场上有「命运女郎·沃特莉」以外的「命运女郎」怪兽存在，这张卡特殊召唤成功的场合发动。自己从卡组抽2张。'),
(82693917, 'Fortune Lady Wind', '命运女郎·温蒂', 'フォーチュンレディ・ウインディー', 'Effect Monster', 'Spellcaster', 'WIND', 3, -1, -1, '这张卡的攻击力·守备力变成这张卡的等级×300的数值。自己的准备阶段时，这张卡的等级上升1星（等级最多12星）。这张卡召唤成功时，可以把自己场上表侧表示存在的名字带有「命运女郎」的怪兽数量的对方场上存在的魔法·陷阱卡破坏。'),
(91407982, 'Fortune Vision', '命运视界', 'フォーチュン・ヴィジョン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1张「命运女郎」卡加入手卡。 ②：1回合1次，自己场上的卡被效果除外的场合才能发动。这个回合，自己场上的怪兽不会被效果破坏。 ③：1回合1次，对方场上的卡被效果除外的场合才能发动。这个回合，自己受到的战斗伤害只有1次变成0。'),
(68663748, 'Fortune''s Future', '命运未来', 'フォーチュンフューチャー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以除外的1只自己的「命运女郎」怪兽为对象才能发动。那只怪兽回到墓地。那之后，自己从卡组抽2张。'),
(47325505, 'Fossil Dig', '化石调查', '化石調査', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只6星以下的恐龙族怪兽加入手卡。'),
(12015000, 'Fossil Dragon Skullgar', '新生代化石龙 骷髅岩壁龙', '新生代化石竜 スカルガー', 'Fusion Monster', 'Rock', 'EARTH', 4, 2500, NULL, '岩石族怪兽＋对方墓地的4星以下的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：把墓地的这张卡除外才能发动。从卡组把1张「化石融合」加入手卡。'),
(21225115, 'Fossil Dragon Skullgios', '古生代化石龙 骷髅屠魔龙', '古生代化石竜 スカルギオス', 'Fusion Monster', 'Rock', 'EARTH', 8, 3500, NULL, '岩石族怪兽＋对方墓地的7星以上的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。 ①：这张卡和对方怪兽进行战斗的伤害计算前才能发动。那只对方怪兽的攻击力和守备力直到那次伤害步骤结束时交换。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：融合召唤的这张卡和对方怪兽的战斗给与对方的战斗伤害变成2倍。'),
(42009836, 'Fossil Dyna Pachycephalo', '化石恐龙 肿头龙', 'フォッシル・ダイナ パキケファロ', 'Effect Monster', 'Rock', 'EARTH', 4, 1200, 1300, '①：这张卡反转的场合发动。场上的特殊召唤的怪兽全部破坏。 ②：只要这张卡在怪兽区域存在，双方不能把怪兽特殊召唤。'),
(23869735, 'Fossil Excavation', '化石发掘', '化石発掘', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以自己墓地1只恐龙族怪兽为对象才能把这张卡发动。那只恐龙族怪兽特殊召唤。 ②：这张卡的①的效果特殊召唤的怪兽只要这张卡在魔法与陷阱区域存在效果无效化，这张卡从场上离开时破坏。那只怪兽破坏时这张卡破坏。'),
(59419719, 'Fossil Fusion', '化石融合', '化石融合－フォッシル・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从自己·对方的墓地把「化石」融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。这个效果从双方墓地把怪兽除外的场合，那只特殊召唤的怪兽不会成为怪兽的效果的对象。 ②：这张卡在墓地存在，自己场上的表侧表示的「化石」融合怪兽被战斗·效果破坏的场合才能发动。墓地的这张卡加入手卡。'),
(10040267, 'Fossil Machine Skull Buggy', '新生代化石机动车 骷髅全地形车', '新生代化石マシン スカルバギー', 'Fusion Monster', 'Rock', 'EARTH', 4, 1400, 1200, '自己墓地的岩石族怪兽＋4星以下的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡战斗破坏对方怪兽时才能发动。给与对方600伤害。 ②：把墓地的这张卡除外才能发动。从卡组把有「化石融合」的卡名记述的1只怪兽加入手卡。'),
(57157964, 'Fossil Machine Skull Convoy', '古生代化石机动车 骷髅大卡车', '古生代化石マシン スカルコンボイ', 'Fusion Monster', 'Rock', 'EARTH', 8, 2100, 1800, '自己墓地的岩石族怪兽＋7星以上的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。 ①：只要融合召唤的这张卡在怪兽区域存在，对方场上的怪兽的攻击力下降那怪兽的原本守备力数值。 ②：这张卡在同1次的战斗阶段中最多3次可以向怪兽攻击。 ③：这张卡战斗破坏对方怪兽时才能发动。给与对方1000伤害。'),
(83656563, 'Fossil Machine Skull Wagon', '中生代化石机动车 骷髅旅行车', '中生代化石マシン スカルワゴン', 'Fusion Monster', 'Rock', 'EARTH', 6, 1700, 1500, '自己墓地的岩石族怪兽＋5·6星的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ②：这张卡战斗破坏对方怪兽时才能发动。给与对方800伤害。 ③：把墓地的这张卡除外，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(17706537, 'Fossil Tusker', '长毛兽化石', 'マンモ・フォッシル', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, NULL, '这张卡战斗破坏对方怪兽送去墓地时，给与对方基本分400分伤害。'),
(86520461, 'Fossil Warrior Skull Bone', '新生代化石骑士 骷髅兵卒', '新生代化石騎士 スカルポーン', 'Fusion Monster', 'Rock', 'EARTH', 4, 2000, 800, '岩石族怪兽＋4星以下的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ②：把墓地的这张卡除外才能发动。从卡组把1张「时间流」加入手卡。'),
(96897184, 'Fossil Warrior Skull King', '古生代化石骑士 骷髅国王', '古生代化石騎士 スカルキング', 'Fusion Monster', 'Rock', 'EARTH', 8, 2800, 1300, '岩石族怪兽＋7星以上的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：这张卡在同1次的战斗阶段中可以作2次攻击。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：对方回合，以对方墓地1只怪兽为对象才能发动。选自己1张手卡丢弃，作为对象的怪兽在自己场上特殊召唤。'),
(59531356, 'Fossil Warrior Skull Knight', '中生代化石骑士 骷髅骑士', '中生代化石騎士 スカルナイト', 'Fusion Monster', 'Rock', 'EARTH', 6, 2400, 1100, '岩石族怪兽＋5·6星的怪兽 这张卡用「化石融合」的效果才能从额外卡组特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡的攻击破坏怪兽时才能发动。这张卡只再1次可以继续攻击。 ③：把墓地的这张卡除外，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(43785278, 'Foucault''s Cannon', '傅科的魔炮石', 'フーコーの魔砲石', 'Pendulum Normal Monster', 'Spellcaster', 'DARK', 5, 2200, 1200, '是彷徨于梦幻空间的机关生命体，本应是如此。 最大的谜团是，过去的记录却几乎··留下来。 那理由···呢，·····干涉···它在···拒··？ ···消去···'),
(27519978, 'Four Charmers in Profusion', NULL, NULL, 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 1850, NULL, NULL),
(88753985, 'Fox Fire', '狐火', 'きつね火', 'Effect Monster', 'Pyro', 'FIRE', 2, 300, 200, '场上表侧表示存在的这张卡被战斗破坏送去墓地的回合的结束阶段时，这张卡从墓地特殊召唤。这张卡只要在场上表侧表示存在，不能为上级召唤而解放。'),
(27198002, 'Fox Token', '九尾狐', '九尾の狐', 'Token', 'Zombie', NULL, NULL, NULL, NULL, NULL),
(72029628, 'Fragment Fusion', '废石融合', '廃石融合', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己墓地把「宝石骑士」融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(69584564, 'Fragrance Storm', '芳香风暴', 'フレグランス・ストーム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只植物族怪兽为对象才能发动。那只植物族怪兽破坏，自己从卡组抽1张。那张抽到的卡是植物族怪兽的场合，可以再把那张卡给双方确认并让自己从卡组抽1张。'),
(26781870, 'Fraud Freeze', '老千御法度', 'イカサマ御法度', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，对方从手卡把怪兽特殊召唤时才能发动。从手卡特殊召唤的对方场上的怪兽全部回到持有者手卡。 ②：场上没有「花札卫」同调怪兽存在的场合这张卡送去墓地。'),
(75025112, 'Free-Range Monsters', '魍魉跋扈', '魍魎跋扈', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段才能发动。把1只怪兽通常召唤。'),
(16556849, 'Freed the Brave Wanderer', '流浪勇者 弗里德', '放浪の勇者 フリード', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1200, '可以把自己墓地存在的2只光属性怪兽从游戏中除外，选择持有比场上表侧表示存在的这张卡的攻击力高的攻击力的场上表侧表示存在的1只怪兽破坏。这个效果1回合只能使用1次。'),
(49681811, 'Freed the Matchless General', '无败将军 弗里德', '無敗将軍 フリード', 'Effect Monster', 'Warrior', 'EARTH', 5, 2300, 1700, '只要这张卡在场上表侧表示存在，这张卡为对象的魔法卡的效果无效并破坏。只要这张卡在场上表侧表示存在，可以作为自己的抽卡阶段时进行通常抽卡的代替，从自己卡组把1只4星以下的战士族怪兽加入手卡。'),
(85359414, 'Freezing Beast', '冰岩魔兽', '氷岩魔獣', 'Union Effect Monster', 'Aqua', 'WATER', 4, 1500, 1000, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「灼岩魔兽」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽对对方造成战斗伤害的场合，破坏场上1张里侧表示的魔法或者陷阱卡。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(43582229, 'Freezing Chains of the Ice Barrier', '冰结界的晶壁', '氷結界の晶壁', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡的发动时，可以以自己墓地1只4星以下的「冰结界」怪兽为对象。那个场合，那只怪兽特殊召唤。 ②：只要这张卡在魔法与陷阱区域存在并在自己场上有「冰结界」怪兽3只以上存在，自己场上的「冰结界」怪兽不受从额外卡组特殊召唤的对方怪兽发动的效果影响。'),
(47219274, 'Freki the Runick Fangs', '神碑之牙 弗力奇', '神碑の牙フレーキ', 'Fusion Monster', 'Beast', 'DARK', 5, 2000, NULL, '「神碑」怪兽×2 这个卡名的③的效果1回合只能使用1次。 ①：额外怪兽区域的这张卡进行战斗的攻击宣言时才能发动。从对方卡组上面把2张卡除外。 ②：这张卡的战斗发生的双方的战斗伤害变成0。 ③：场上的这张卡被战斗·效果破坏的场合，以自己墓地1张「神碑」速攻魔法卡为对象才能发动。那张卡加入手卡。'),
(98818516, 'Frenzied Panda', '杀手熊猫', 'キラーパンダ', 'Normal Monster', 'Beast', 'EARTH', 4, 1200, 1000, '经常手持一根粗大的竹子四处找茬，性格非常凶暴。'),
(62154416, 'Frequency Magician', '魔力美容师', 'マジカルフィシアリスト', 'Tuner Monster', 'Spellcaster', 'LIGHT', 2, 800, 400, '这张卡召唤成功时，给这张卡放置1个魔力指示物（最多1个）。此外，自己的主要阶段时可以通过把这张卡放置的1个魔力指示物取除，选择自己场上1只怪兽那个攻击力直到结束阶段时上升500。'),
(12398280, 'Freya, Spirit of Victory', '胜利的引导者 芙蕾雅', '勝利の導き手フレイヤ', 'Effect Monster', 'Fairy', 'LIGHT', 1, 100, 100, '自己场上有「胜利的引导者 芙蕾雅」以外的天使族怪兽表侧表示存在的场合，这张卡不能被选择作为攻击对象。只要这张卡在自己场上表侧表示存在，自己场上存在的天使族怪兽的攻击力·守备力上升400。'),
(85545073, 'Frightfur Bear', '魔玩具・剪刀熊', 'デストーイ・シザー・ベアー', 'Fusion Monster', 'Fiend', 'DARK', 6, 2200, 1800, '「锋利小鬼·剪刀」＋「毛绒动物·熊」 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽当作攻击力上升1000的装备卡使用给这张卡装备。'),
(83866861, 'Frightfur Chimera', '魔玩具·狂乱奇美拉', 'デストーイ・マッド・キマイラ', 'Fusion Monster', 'Fiend', 'DARK', 8, 2800, 2000, '「魔玩具」怪兽×3 这张卡不用融合召唤不能特殊召唤。「魔玩具·狂乱奇美拉」的②的效果1回合只能使用1次。 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ②：这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽的攻击力变成一半在自己场上特殊召唤。 ③：这张卡的攻击力上升原本持有者是对方的自己场上的怪兽数量×300。'),
(78778375, 'Frightfur Cruel Whale', '魔玩具・残酷鲸', 'デストーイ・クルーエル・ホエール', 'Fusion Monster', 'Fiend', 'WATER', 9, 2600, 2400, '「锋利小鬼」怪兽＋「毛绒动物」怪兽 ①：这张卡融合召唤成功的场合才能发动。选自己以及对方场上的卡各1张破坏。 ②：1回合1次，以自己场上1只融合怪兽为对象才能发动。从卡组·额外卡组把「魔玩具·残虐虎鲸」以外的1张「魔玩具」卡送去墓地，作为对象的怪兽的攻击力直到回合结束时上升自身的原本攻击力一半数值。这个效果在对方回合也能发动。'),
(91034681, 'Frightfur Daredevil', '魔玩具·冒失鬼', 'デストーイ・デアデビル', 'Fusion Monster', 'Fiend', 'DARK', 8, 3000, 2200, '「锋利小鬼」怪兽＋「毛绒动物」怪兽 「魔玩具·冒失鬼」的②的效果1回合只能使用1次。 ①：这张卡战斗破坏对方怪兽时才能发动。给与对方1000伤害。 ②：表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。给与对方为自己墓地的「魔玩具」怪兽数量×500伤害。'),
(43698897, 'Frightfur Factory', '魔玩具工厂', 'デストーイ・ファクトリー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「魔玩具工厂」的①②的效果1回合各能使用1次。 ①：从自己墓地把1张「融合」魔法卡除外才能把这个效果发动。从自己的手卡·场上把「魔玩具」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：这张卡被送去墓地的场合，以除外的1张自己的「魔玩具融合」为对象才能发动。那张卡加入手卡。'),
(6077601, 'Frightfur Fusion', '魔玩具结合', '魔玩具融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「魔玩具融合」在1回合只能发动1张。 ①：从自己的场上·墓地把「魔玩具」融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。'),
(18138630, 'Frightfur Jar', '魔玩具厄瓶', '魔玩具厄瓶', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡的卡名只要在场上·墓地存在当作「玩具罐」使用。 ②：1回合1次，丢弃1张手卡才能发动。自己从卡组抽1张，给双方确认。那是「锋利小鬼」怪兽的场合，可以选场上1张卡破坏。不是的场合，选1张手卡回到卡组最上面或者最下面。 ③：这张卡被送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成一半。'),
(40636712, 'Frightfur Kraken', '魔玩具・钩手海怪', 'デストーイ・ハーケン・クラーケン', 'Fusion Monster', 'Fiend', 'WATER', 8, 2200, 3000, '「锋利小鬼」怪兽＋「毛绒动物」怪兽 ①：1回合1次，以对方场上1只怪兽为对象才能发动。那只怪兽送去墓地。这个效果发动的回合，这张卡不能直接攻击。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。 ③：这张卡进行战斗的战斗阶段结束时才能发动。这张卡变成守备表示。'),
(10383554, 'Frightfur Leo', '魔玩具·轮锯狮', 'デストーイ・ホイールソウ・ライオ', 'Fusion Monster', 'Fiend', 'DARK', 7, 2400, 2000, '「锋利小鬼·锯子」＋「毛绒动物」怪兽 这张卡不用融合召唤不能特殊召唤。「魔玩具·轮锯狮」的效果1回合只能使用1次，这个效果发动的回合，这张卡不能直接攻击。 ①：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏，给与对方破坏的怪兽的原本攻击力数值的伤害。'),
(74416026, 'Frightfur March', '魔玩具行进', 'デストーイ・マーチ', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上的「魔玩具」怪兽为对象的怪兽的效果·魔法·陷阱卡由对方发动时才能发动。那个发动无效并破坏。那之后，以下效果可以适用。 ●成为对象的1只「魔玩具」怪兽送去墓地，把1只8星以上的「魔玩具」融合怪兽当作融合召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽在下次的自己结束阶段除外。'),
(77522571, 'Frightfur Meister', '魔玩具大师', 'デストーイ・マイスター', 'Pendulum Effect Monster', 'Fiend', 'DARK', 8, NULL, NULL, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组把4星以下的「魔玩具」、「毛绒动物」、「锋利小鬼」怪兽的其中1只特殊召唤。这个回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ②：把自己场上的恶魔族怪兽2只以上解放才能发动。把持有和那个原本等级合计相同等级的1只「魔玩具」融合怪兽当作融合召唤从额外卡组特殊召唤。'),
(34773082, 'Frightfur Patchwork', '魔玩具补缀', '魔玩具補綴', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张「融合」和1只「锋利小鬼」怪兽加入手卡。'),
(28039390, 'Frightfur Reborn', '魔玩具重织', 'デストーイ・リニッチ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「魔玩具」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把墓地的这张卡除外，以除外的1只自己的「毛绒动物」怪兽或者「魔玩具」怪兽为对象才能发动。那只怪兽回到墓地。这个效果在这张卡送去墓地的回合不能发动。'),
(99049589, 'Frightfur Repair', '魔玩具修理', 'デストーイ・リペアー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己墓地1只「魔玩具」融合怪兽为对象才能发动。那只怪兽回到额外卡组。那之后，可以从自己墓地选1只「毛绒动物」怪兽或者「锋利小鬼」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。从手卡把1只「毛绒动物」怪兽或者「锋利小鬼」怪兽特殊召唤。'),
(80889750, 'Frightfur Sabre-Tooth', '魔玩具・刺刀虎', 'デストーイ・サーベル・タイガー', 'Fusion Monster', 'Fiend', 'DARK', 8, 2400, 2000, '「魔玩具」融合怪兽＋「毛绒动物」怪兽或者「锋利小鬼」怪兽1只以上 ①：这张卡融合召唤成功时，以自己墓地1只「魔玩具」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的「魔玩具」怪兽的攻击力上升400。 ③：怪兽3只以上为素材作融合召唤的这张卡不会被战斗·效果破坏。'),
(74839123, 'Frightfur Sanctuary', '魔玩具圣域', 'デストーイ・サンクチュアリ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '丢弃1张手卡，从自己的额外卡组把2只「魔玩具」怪兽送去墓地才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，自己场上的全部融合怪兽也当作「魔玩具」怪兽使用。 ②：这张卡被送去墓地的场合，以自己墓地1只「魔玩具」融合怪兽为对象才能发动。那只怪兽回到额外卡组。'),
(57477163, 'Frightfur Sheep', '魔玩具・锁链羊', 'デストーイ・チェーン・シープ', 'Fusion Monster', 'Fiend', 'DARK', 5, 2000, 2000, '「锋利小鬼·链子」＋「毛绒动物」怪兽 「魔玩具·链绵羊」的②的效果1回合只能使用1次。 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ②：这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡的攻击力上升800。'),
(464362, 'Frightfur Tiger', '魔玩具・剪刀虎', 'デストーイ・シザー・タイガー', 'Fusion Monster', 'Fiend', 'DARK', 6, 1900, 1200, '「锋利小鬼·剪刀」＋「毛绒动物」怪兽1只以上 ①：「魔玩具·剪刀虎」在自己场上只能有1只表侧表示存在。 ②：这张卡融合召唤成功时，以最多有作为这张卡的融合素材的怪兽数量的场上的卡为对象才能发动。那些卡破坏。 ③：只要这张卡在怪兽区域存在，自己场上的「魔玩具」怪兽的攻击力上升自己场上的「毛绒动物」怪兽以及「魔玩具」怪兽数量×300。'),
(11039171, 'Frightfur Wolf', '魔玩具・剪刀狼', 'デストーイ・シザー・ウルフ', 'Fusion Monster', 'Fiend', 'DARK', 6, 2000, 1500, '「锋利小鬼·剪刀」＋「毛绒动物」怪兽1只以上 这张卡用以上记的卡为融合素材的融合召唤才能特殊召唤。 ①：这张卡在同1次的战斗阶段中可以作出最多有作为这张卡的融合素材的怪兽数量的攻击。'),
(93830681, 'Friller Rabca', '杀人皱鳃鲨', 'キラー・ラブカ', 'Effect Monster', 'Fish', 'WATER', 3, 700, 1500, '自己场上表侧表示存在的鱼族·海龙族·水族怪兽被选择作为攻击对象时，把墓地存在的这张卡从游戏中除外发动。把1只攻击怪兽的攻击无效，那个攻击力直到下次的自己的结束阶段时下降500。「杀人皱鳃鲨」的效果1回合只能使用1次。'),
(40998517, 'Frodi, Generaider Boss of Swords', '剑之创王 弗洛迪', '剣の王 フローディ', 'Effect Monster', 'Warrior', 'WIND', 9, 2500, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：「剑界王战 弗罗德王」在自己场上只能有1只表侧表示存在。 ②：把自己场上的「王战」怪兽或者战士族怪兽任意数量解放，以那个数量的场上的怪兽为对象才能发动。那些怪兽破坏。那之后，对方可以从卡组抽出破坏的对方场上的怪兽的数量。这个效果在对方回合也能发动。'),
(34351849, 'Froggy Forcefield', '蛙类防护罩', 'フロッグ・バリア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「青蛙」的怪兽被选择作为攻击对象时才能发动。对方场上存在的攻击表示怪兽全部破坏。'),
(38742075, 'Frontier Wiseman', '边境的大贤者', '辺境の大賢者', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1600, 800, '只要这张卡在自己的场上存在，以自己场上的表侧表示存在的战士族怪兽为对象的魔法卡的效果无效并破坏。'),
(46181000, 'Frontline Base', '前线基地', '前線基地', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，自己的主要阶段时可以从手卡把1只4星以下的同盟怪兽特殊召唤。'),
(12451640, 'Frontline Observer', '前线观察员', 'フロント・オブザーバー', 'Effect Monster', 'Machine', 'EARTH', 4, 1000, 1500, '①：这张卡召唤成功的回合的结束阶段才能发动。从卡组把1只地属性灵摆怪兽加入手卡。 ②：这张卡召唤成功的场合，下次的自己回合的结束阶段，把这张卡解放才能发动。从卡组把1只地属性怪兽加入手卡。'),
(55589254, 'Frost and Flame Dragon', '冰炎之双龙', '氷炎の双竜', 'Effect Monster', 'Dragon', 'WATER', 6, 2300, 2000, '这张卡不能通常召唤。把自己墓地2只水属性怪兽和1只炎属性怪兽从游戏中除外的场合才能特殊召唤。1回合1次，丢弃1张手卡才能发动。选择场上1只怪兽破坏。'),
(99940363, 'Frost Blast of the Monarchs', '帝王的冻气', '帝王の凍気', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有攻击力2400以上而守备力1000的怪兽存在的场合，以场上盖放的1张卡为对象才能发动。那张卡破坏。 ②：从自己墓地把这张卡和1张「帝王」魔法·陷阱卡除外，以场上盖放的1张卡为对象才能发动。那张卡破坏。'),
(6631034, 'Frostosaurus', '冰霜龙', 'フロストザウルス', 'Normal Monster', 'Dinosaur', 'WATER', 6, 2600, 1700, '托迟钝的神经和感性的福，拥有被冰封却熬过冰河期的威胁性生命力。耐寒可是异常强哟。'),
(35380371, 'Frozen Domain of the Ice Barrier', '抵达冰结界的晶域', '氷結界に至る晶域', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方不能对应自己的「冰结界」怪兽的效果的发动把魔法·陷阱·怪兽的效果发动。 ②：从额外卡组有怪兽特殊召唤的场合才能发动。选自己场上1只「冰结界」怪兽回到手卡或卡组。那之后，可以让自己或对方的场上·墓地1张卡回到卡组最下面。 ③：自己结束阶段发动。从额外卡组把3只卡名不同的「冰结界」怪兽给对方观看或这张卡破坏。'),
(94515289, 'Frozen Fitzgerald', '冰结之菲茨杰拉德', '氷結のフィッツジェラルド', 'Synchro Monster', 'Fiend', 'WATER', 5, 2500, 2500, '暗属性调整＋调整以外的兽族怪兽1只 这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。这张卡被战斗破坏送去墓地时，自己场上没有怪兽存在的场合，可以丢弃1张手卡把这张卡从墓地表侧守备表示特殊召唤。'),
(53503015, 'Frozen Rose', '冷香蔷薇之抱吼', '冷薔薇の抱香', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示怪兽送去墓地才能发动。那只怪兽种族的以下效果适用。 ●植物族：这个回合的结束阶段，自己从卡组抽2张，那之后选1张手卡丢弃。 ●植物族以外：从卡组把1只4星以下的植物族怪兽加入手卡。'),
(57069605, 'Frozen Soul', '魂之冰结', '魂の氷結', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '当自己的基本分比对方的基本分少2000以上时这张卡才能发动。略过对方的下一个战斗阶段。'),
(49998907, 'Fruits of Kozaky''s Studies', '平庸鬼的研究成果', 'コザッキーの研究成果', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己卡组最上面3张卡确认，并且把那些卡按照自己的意愿交换顺序放回卡组最上面。'),
(1781310, 'Fuh-Rin-Ka-Zan', '风林火山', '風林火山', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：风·水·炎·地属性怪兽在场上全部存在的场合才能发动。从以下效果选1个适用。 ●对方场上的怪兽全部破坏。 ●对方场上的魔法·陷阱卡全部破坏。 ●对方手卡随机选2张丢弃。 ●自己从卡组抽2张。'),
(9373534, 'Fuhma Shuriken', '风魔手里剑', '風魔手裏剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名称中含有「忍者」字样的怪兽才能装备这张卡。装备这张卡的怪兽攻击力上升700点。这张卡从场上送去墓地时，给与对方基本分700分的伤害。'),
(2994495, 'Fuhma Wave', '风魔的波动', '風魔の波動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。选和那只怪兽卡名不同并持有相同属性的场上1只怪兽破坏。'),
(54927180, 'Fukubiki', '福悲喜', '福悲喜', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方玩家把卡组洗切，卡组最上面的卡翻开并把那些卡的攻击力确认（攻击力?的怪兽或者魔法·陷阱卡的场合那个攻击力当作0使用）。攻击力较高方的卡加入那个玩家的手卡，攻击力较低方的卡送去墓地。攻击力相同的场合，那些卡回到卡组最下面。'),
(48206762, 'Fulfillment of the Contract', '契约履行', '契約の履行', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '支付800基本分。从自己墓地选择1只仪式怪兽在自己场上特殊召唤，并装备上这张卡。这张卡破坏时，装备怪兽从游戏中除外。'),
(4483598, 'Full Active Duplex', '全主动双工霸王龙', 'フルアクティブ・デュプレックス', 'Effect Monster', 'Cyberse', 'WIND', 9, 2800, 1000, '这个卡名的①③的效果1回合各能使用1次。 ①：从自己墓地把2只连接怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：连接状态的自己怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：这张卡被送去墓地的场合，以自己场上1只电子界族怪兽为对象才能发动。那只怪兽的攻击力上升1000。'),
(25853045, 'Full Armored Black Ray Lancer', '全装甲－黑鳍枪兵', 'FA－ブラック・レイ・ランサー', 'XYZ Monster', 'Beast-Warrior', 'WATER', 4, 2100, 600, '水属性4星怪兽×3 这张卡也能在自己场上的没有超量素材的3阶水属性超量怪兽上面重叠来超量召唤。 ①：这张卡的攻击力上升这张卡的超量素材数量×200。 ②：这张卡战斗破坏对方怪兽时，以对方场上1张魔法·陷阱卡为对象才能发动。那张对方的卡破坏。 ③：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡的超量素材全部取除。'),
(99469936, 'Full Armored Crystalzero Lancer', '全装甲－水晶零枪兵', 'FA－クリスタル・ゼロ・ランサー', 'XYZ Monster', 'Warrior', 'WATER', 6, 2200, 1600, '水属性6星怪兽×3 这张卡也能在自己场上的5阶水属性超量怪兽上面重叠来超量召唤。 ①：这张卡的攻击力上升这张卡的超量素材数量×500。 ②：1回合1次，把这张卡1个超量素材取除才能发动。对方场上的全部表侧表示怪兽的效果直到回合结束时无效。 ③：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(67630394, 'Full Armored Dark Knight Lancer', '全装甲－黑暗骑士枪兵', 'FA－ダーク・ナイト・ランサー', 'XYZ Monster', 'Aqua', 'WATER', 7, 2800, 1500, '7星怪兽×3 「重铠装-暗黑骑士枪兵」1回合1次也能在自己场上的5·6阶的超量怪兽上面重叠来超量召唤。 ①：这张卡的攻击力上升这张卡的超量素材和装备卡数量×300。 ②：1回合1次，以自己墓地1张「超量」卡为对象才能发动。那张卡加入手卡。 ③：1回合1次，自己场上的怪兽有装备卡被装备的场合才能发动。把对方场上1只怪兽作为这张卡的超量素材。'),
(1269512, 'Full Armored Utopic Ray Lancer', '全装甲－霍普鳍枪兵', 'FA－ホープ・レイ・ランサー', 'XYZ Monster', 'Beast-Warrior', 'WATER', 4, 2500, 600, '4星怪兽×3 「重铠装-希望鳍条枪兵」1回合1次也能把手卡1张魔法·陷阱卡丢弃，在自己场上的4阶以下的超量怪兽上面重叠来超量召唤。 ①：对方场上的怪兽的攻击力下降500。 ②：自己·对方的战斗阶段开始时才能发动。对方场上的全部攻击表示怪兽的效果无效化。 ③：这张卡的攻击破坏对方怪兽时，把这张卡1个超量素材取除才能发动。这张卡只再1次可以继续攻击。'),
(4931121, 'Full Force Virus', '影之卡组破坏病毒', '影のデッキ破壊ウイルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只守备力2000以上的暗属性怪兽解放才能发动。对方场上的怪兽，对方手卡，用对方回合计算的3回合内对方抽到的卡全部确认，那之内的守备力1500以下的怪兽全部破坏。'),
(45178472, 'Full House', '满堂红', 'フルハウス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择这张卡以外的场上表侧表示存在的2张魔法·陷阱卡和盖放的3张魔法·陷阱卡才能发动。选择的卡破坏。'),
(70865988, 'Full Salvo', '全弹发射', '全弾発射', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动后，把手卡全部送去墓地。给与对方基本分送去墓地的卡数量×200数值的伤害。'),
(39733924, 'Full-Armored Xyz', '全装甲超量', 'フル・アーマード・エクシーズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有超量怪兽存在的场合才能发动。进行1只超量怪兽的超量召唤。 ②：把墓地的这张卡除外，以自己场上1只超量怪兽为对象才能发动。那只怪兽以外的自己的场上（表侧表示）·墓地1只超量怪兽当作持有以下效果的装备魔法卡使用给作为对象的怪兽装备。 ●装备怪兽的攻击力上升这张卡的攻击力数值。 ●装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。'),
(81000306, 'Full-Force Strike', '浑身一击', '渾身の一撃', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽发动。这个回合，选择的怪兽不会被战斗破坏，那次攻击发生的对双方的战斗伤害变成0。此外，这个回合，选择的怪兽向对方怪兽攻击的场合，伤害计算后那只对方怪兽破坏。'),
(17201951, 'Full-Speed Warrior', '极驰高速战士', 'フルスピード・ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 2, 900, 400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。把1只「废品同调士」或者1张有「废品战士」的卡名记述的魔法·陷阱卡从卡组加入手卡。 ②：只要这张卡在怪兽区域存在，自己场上的以下怪兽的攻击力只在自己战斗阶段内上升900。 ●有「废品战士」的卡名记述的怪兽 ●原本卡名包含「战士」的同调怪兽'),
(77693536, 'Fullmetalfoes Alkahest', '重炼装勇士·万溶炼金师', 'フルメタルフォーゼ・アルカエスト', 'Fusion Monster', 'Psychic', 'FIRE', 1, NULL, NULL, '「炼装」怪兽＋通常怪兽 这张卡不用融合召唤不能特殊召唤。 ①：对方回合1次，以场上1只效果怪兽为对象才能发动。那只效果怪兽当作装备卡使用给这张卡装备。 ②：这张卡的守备力上升这张卡的效果装备的怪兽的原本攻击力数值。 ③：这张卡有由「炼装」融合怪兽卡决定的融合素材怪兽装备的场合，可以把那装备卡作为那只融合怪兽的融合素材使用。'),
(39564736, 'Fullmetalfoes Fusion', '重炼装融合', '重錬装融合', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上把「炼装」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(53830602, 'Fungi of the Musk', '魔界植物', '魔界植物', 'Normal Monster', 'Fiend', 'DARK', 1, 400, 300, '从割面发出强力的酸液融化接近的人。'),
(59374259, 'Furtive Techniques Fur Hire, Fur All Your Ultimate Moves', '空牙团的奥义', '空牙団の奥義', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以最多有自己场上的「空牙团」怪兽种类数量的场上的表侧表示卡为对象才能发动。那些卡破坏。自己场上有8星以上以及连接3以上的「空牙团」怪兽各存在的场合，也能作为代替把作为对象的卡全部除外。 ②：这张卡在墓地存在的状态，自己场上有8星以上或连接3以上的「空牙团」怪兽特殊召唤的场合才能发动。这张卡加入手卡。'),
(92345028, 'Fury of Fire', '火焰狂暴', 'フューリー・オブ・ファイア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「转生炎兽」卡使用。这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地选最多2只「转生炎兽」怪兽守备表示特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽的效果无效化。这张卡的发动后，直到回合结束时自己只能有1次从额外卡组把怪兽特殊召唤。'),
(98804359, 'Fury of Kairyu-Shin', '海龙神的激昂', '海竜神の激昂', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1张「激流葬」加入手卡。 ②：自己场上的水属性怪兽被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(300302005, 'Fury of Thunder', NULL, NULL, 'Skill Card', 'Yami Yugi', NULL, NULL, NULL, NULL, NULL),
(51091138, 'Fuse Line', '导爆线', '導爆線', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以和这张卡相同纵列的1张卡为对象才能把盖放的这张卡发动。那张卡破坏。'),
(38538445, 'Fushi No Tori', '不死之炎鸟', '不死之炎鳥', 'Spirit Monster', 'Winged Beast', 'FIRE', 4, 1200, NULL, '这张卡不能特殊召唤。召唤·反转回合的结束阶段时回到主人的手卡。这张卡给与对方玩家战斗伤害的场合，自己的基本分回复那个战斗伤害的数值。'),
(39711336, 'Fushioh Richie', '不死王 巫妖', '不死王リッチー', 'Effect Monster', 'Zombie', 'DARK', 7, 2600, 2900, '这张卡不能通常召唤。满足条件的「大神官 迪·扎德」做祭品特殊召唤。这张卡1个回合可以有1次变成里侧守备表示。场上表侧表示存在的这张卡为对象的魔法·陷阱卡的发动和效果无效并破坏。这张卡反转时，选择自己的墓地的1只不死族怪兽特殊召唤上场。'),
(51632798, 'Fusilier Dragon, the Dual-Mode Beast', '可变机兽 炮手龙', '可変機獣 ガンナードラゴン', 'Effect Monster', 'Machine', 'DARK', 7, 2800, 2000, '①：这张卡可以不用解放作通常召唤。 ②：这张卡的①的方法通常召唤的这张卡的原本的攻击力·守备力变成一半。'),
(61070601, 'Fusion Armament', '融合强兵', '融合強兵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把额外卡组1只融合怪兽给对方观看，那只怪兽有卡名记述的1只融合素材怪兽从自己的额外卡组·墓地特殊召唤。这个效果特殊召唤的怪兽直到对方回合结束时不能攻击，效果无效化。'),
(17194258, 'Fusion Conscription', '融合征兵', '融合徴兵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把额外卡组1只融合怪兽给对方观看，从自己的卡组·墓地选那只怪兽有卡名记述的1只融合素材怪兽加入手卡。这张卡的发动后，直到回合结束时自己不能把这个效果加入手卡的怪兽以及那些同名怪兽通常召唤·特殊召唤，那些怪兽效果不能发动。'),
(6498706, 'Fusion Deployment', '融合派兵', '融合派兵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ①：把额外卡组1只融合怪兽给对方观看，那只怪兽有卡名记述的1只融合素材怪兽从手卡·卡组特殊召唤。'),
(52947044, 'Fusion Destiny', '结合命运', 'フュージョン・デステニー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的手卡·卡组的怪兽作为融合素材，把以「命运英雄」怪兽为融合素材的1只融合怪兽融合召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段破坏。这张卡的发动后，直到回合结束时自己不是暗属性「英雄」怪兽不能特殊召唤。'),
(98336111, 'Fusion Devourer', '融合体杀手', 'フュージョニストキラー', 'Effect Monster', 'Fiend', 'DARK', 4, 1400, 1200, '和这张卡进行战斗的融合怪兽的攻击力在伤害步骤内变成0。'),
(55158350, 'Fusion Draft', '融合募兵', '融合募兵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃1张手卡，把额外卡组1只融合怪兽给对方观看才能发动。除为这个效果发动而丢弃的卡外的1只在给人观看的怪兽有卡名记述的融合素材怪兽从自己的卡组·墓地加入手卡。这个效果把通常怪兽加入手卡的场合，可以再把另1只加入手卡。这张卡的发动后，直到回合结束时自己不是融合怪兽不能从额外卡组特殊召唤。'),
(43331750, 'Fusion Duplication', '结合复制', '融合複製', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己或对方的墓地1张「融合」通常·速攻魔法卡为对象才能发动。那张魔法卡除外。那之后，那张魔法卡发动时的效果适用。'),
(34449261, 'Fusion Fright Waltz', '融合死圆舞曲', '融合死円舞曲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「魔玩具」融合怪兽和对方场上1只融合怪兽为对象才能发动。作为对象的怪兽以外的场上的特殊召唤的怪兽全部破坏。那之后，被这个效果把怪兽破坏的玩家受到作为对象的怪兽的攻击力合计数值的伤害。'),
(33550694, 'Fusion Gate', '结合之门', 'フュージョン・ゲート', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：双方玩家在自己主要阶段才能发动。从自己的手卡·场上把融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。'),
(73026394, 'Fusion Guard', '融合防御', 'フュージョン・ガード', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '给与伤害的效果发动时才能发动。那个发动和效果无效，从自己融合卡组随机把1只融合怪兽送去墓地。'),
(25800447, 'Fusion of Fire', '火焰结合', 'フュージョン・オブ・ファイア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「转生炎兽」卡使用。这个卡名的卡在1回合只能发动1张。 ①：从自己手卡以及自己·对方场上把「转生炎兽」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(6205579, 'Fusion Parasite', '寄生结融者', 'パラサイト・フュージョナー', 'Effect Monster', 'Insect', 'DARK', 1, NULL, NULL, '这张卡在这张卡的①的效果适用的场合才能作为融合素材。 ①：这张卡可以作为融合怪兽卡有卡名记述的1只融合素材怪兽的代替。那个时候，其他的融合素材怪兽必须是正规品。 ②：这张卡特殊召唤成功的场合才能发动。融合怪兽卡决定的包含这张卡的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(300302001, 'Fusion Party!', NULL, NULL, 'Skill Card', 'Christine', NULL, NULL, NULL, NULL, NULL),
(18511384, 'Fusion Recovery', '融合回收', '融合回収', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1张「融合」和1只融合召唤使用过的融合素材怪兽为对象才能发动。那些卡加入手卡。'),
(22829942, 'Fusion Recycling Plant', '融合再生机构', '融合再生機構', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，丢弃1张手卡才能发动。从自己的卡组·墓地选1张「融合」加入手卡。 ②：自己·对方的结束阶段，以这个回合融合召唤使用过的自己墓地1只融合素材怪兽为对象才能发动。那只怪兽加入手卡。'),
(66127916, 'Fusion Reserve', '融合准备', '融合準備', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把额外卡组1只融合怪兽给对方观看，那只怪兽有卡名记述的1只融合素材怪兽从卡组加入手卡。那之后，可以从自己墓地选1张「融合」加入手卡。'),
(26902560, 'Fusion Sage', '融合贤者', '融合賢者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选1张自己的卡组的「融合」加入手卡。之后洗切卡组。'),
(74335036, 'Fusion Substitute', '置换融合', '置換融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的卡名在规则上当作「融合」使用。 ①：从自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：把墓地的这张卡除外，以自己墓地1只融合怪兽为对象才能发动。那只怪兽回到额外卡组。那之后，自己从卡组抽1张。'),
(37684215, 'Fusion Sword Murasame Blade', '融合武器 村雨刀', '融合武器ムラサメブレード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。 ①：装备怪兽的攻击力上升800。 ②：给怪兽装备的这张卡不会被效果破坏。'),
(59432181, 'Fusion Tag', '融合识别', '融合識別', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只怪兽为对象才能发动。把额外卡组1只融合怪兽给对方观看。这个回合，把作为对象的怪兽作为融合素材的场合，可以作为那只给人观看的怪兽的同名卡来成为融合素材。'),
(27967615, 'Fusion Weapon', '融合武器', 'フュージョン・ウェポン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '6星以下的融合怪兽才能装备。装备怪兽的攻击力·守备力上升1500。'),
(1641882, 'Fusionist', '结融体', 'フュージョニスト', 'Fusion Monster', 'Beast', 'EARTH', 3, 900, 700, '「小天使」＋「催眠羊」'),
(55397172, 'Futsu no Mitama no Mitsurugi', '布都御魂之巳剑', '布都御魂之巳剣', 'Ritual Effect Monster', 'Reptile', 'DARK', 8, 2000, 3400, '「巳剑降临」降临 这个卡名的①的效果在同一连锁上只能发动1次，②的效果1回合只能使用1次。 ①：对方把怪兽特殊召唤的场合，以「布都御魂之巳剑」以外的自己墓地1只爬虫类族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡被解放的场合才能发动。从卡组把「布都御魂之巳剑」以外的1张「巳剑」卡加入手卡。那之后，可以把这张卡特殊召唤。'),
(12508268, 'Future Drive', '翼日驱动', 'フューチャー・ドライブ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「未来皇 霍普」超量怪兽为对象才能发动。这个回合，那只自己怪兽受以下效果适用。 ●那只怪兽可以向对方怪兽全部各作1次攻击。 ●那只怪兽和对方怪兽进行战斗的伤害步骤内，那只对方怪兽的效果无效化。 ●每次那只怪兽战斗破坏对方怪兽，给与对方那只破坏的怪兽的原本攻击力数值的伤害。'),
(77565204, 'Future Fusion', '未来融合－永望结合', '未来融合－フューチャー・フュージョン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡的发动后第1次的自己准备阶段发动。额外卡组1只融合怪兽给对方观看，那只怪兽决定的融合素材怪兽从卡组送去墓地。 ②：这张卡的发动后第2次的自己准备阶段发动。把1只和这张卡的①的效果给人观看的怪兽同名的融合怪兽融合召唤。这张卡从场上离开时那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(64107820, 'Future Glow', '未来光辉', 'フューチャー・グロウ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己墓地存在的1只念动力族怪兽从游戏中除外发动。只要这张卡在场上存在，自己场上表侧表示存在的全部念动力族怪兽的攻击力上升因为这张卡发动而除外的怪兽的等级×200的数值。'),
(90642597, 'Future Samurai', '未来侍', '未来サムライ', 'Gemini Monster', 'Warrior', 'LIGHT', 4, 1600, 1200, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●可以把自己墓地存在的1只怪兽从游戏中除外，场上表侧表示存在的1只怪兽破坏。这个效果1回合只能使用1次。'),
(78679226, 'Future Silence', '向未来的沉默', '未来への沈黙', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把有「光之黄金柜」的卡名记述的1只怪兽加入手卡。自己场上有着「光之黄金柜」以及有那个卡名记述的怪兽存在的状态，把这张卡在自己·对方的战斗阶段发动的场合，再让双方各自直到手卡变成6张为止抽卡。'),
(87902575, 'Future Visions', '未来视界', 'フューチャー・ヴィジョン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己或者对方对怪兽的召唤成功时，选择那1只怪兽从游戏中除外。从召唤的怪兽的控制者来看的下次的自己的准备阶段时，这个效果除外的怪兽表侧攻击表示回到场上。'),
(61668670, 'G Golem Crystal Heart', 'G魔像・水晶心', 'Gゴーレム・クリスタルハート', 'Link Monster', 'Cyberse', 'WATER', NULL, NULL, NULL, '电子界族怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只地属性连接怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤，给这张卡放置1个G石人指示物。 ②：这张卡所互相连接区的地属性怪兽攻击力上升这张卡的G石人指示物数量×600，同1次的战斗阶段中可以作2次攻击，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(50546029, 'G Golem Dignified Trilithon', 'G魔像・庄严三巨石', 'Gゴーレム・ディグニファイド・トリリトン', 'Link Monster', 'Cyberse', 'EARTH', NULL, 3200, NULL, '地属性怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：可以攻击的对方怪兽必须向这张卡作出攻击。 ②：这张卡和对方怪兽进行战斗的伤害计算前1次，从手卡把1只地属性怪兽送去墓地才能发动。那只对方怪兽直到回合结束时攻击力下降200，效果无效化。 ③：自己场上的连接怪兽为对象的效果由对方发动时才能发动。那个效果无效并破坏。'),
(24151924, 'G Golem Invalid Dolmen', 'G魔像・无果石墓', 'Gゴーレム・インヴァリッド・ドルメン', 'Link Monster', 'Cyberse', 'EARTH', NULL, 2800, NULL, '地属性怪兽2只以上 ①：只要这张卡在怪兽区域存在，自己场上的互相连接状态的怪兽不受对方场上发动的怪兽的效果影响。 ②：可以攻击的对方怪兽必须向这张卡作出攻击。 ③：1回合1次，从手卡丢弃1只电子界族怪兽才能发动。自己从卡组抽1张。 ④：互相连接状态的这张卡被破坏的场合才能发动。对方场上的全部表侧表示的卡的效果无效化。'),
(25273572, 'G Golem Pebble Dog', 'G魔像・卵石斗牛犬', 'Gゴーレム・ペブルドッグ', 'Effect Monster', 'Cyberse', 'EARTH', 2, 300, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组选1只「G石人·卵石斗牛犬」加入手卡或特殊召唤。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。 ②：这张卡从手卡送去墓地的场合才能发动。从卡组把1张「G石人」卡加入手卡。'),
(98875863, 'G Golem Rock Hammer', 'G魔像・岩锤者', 'Gゴーレム・ロックハンマー', 'Effect Monster', 'Cyberse', 'EARTH', 6, 1800, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从手卡丢弃1只其他的电子界族怪兽才能发动。这个回合，这张卡的等级下降2星。 ②：把这张卡解放才能发动。在自己场上把3只「G石人衍生物」（电子界族·地·1星·攻/守0）守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能特殊召唤。'),
(97053215, 'G Golem Stubborn Menhir', 'G魔像・顽硬巨碑', 'Gゴーレム・スタバン・メンヒル', 'Link Monster', 'Cyberse', 'EARTH', NULL, 1500, NULL, '地属性怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡从墓地的特殊召唤成功的场合，以自己墓地1只可以通常召唤的地属性怪兽为对象才能发动。那只怪兽加入手卡或特殊召唤。这个效果特殊召唤的怪兽的效果无效化，从场上离开的场合除外。'),
(4130270, 'G.B. Hunter', 'G·B·猎人', 'G・B・ハンター', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 2000, '只要这张卡在场上表侧表示存在，场上存在的卡不能回到卡组。'),
(37955049, 'Gaap the Divine Soldier', '军神 概布', '軍神ガープ', 'Effect Monster', 'Fiend', 'DARK', 6, 2200, 2000, '只要这张卡在场上表侧表示存在，场上存在的怪兽全部变成表侧攻击表示，表示形式不能改变。（这个时候，反转效果怪兽的效果不发动。）此外，1回合只有1次可以把手卡的恶魔族怪兽给对方观看，这张卡的攻击力直到结束阶段时上升观看的卡数量×300的数值。'),
(6616912, 'Gabrion, the Timelord', '时械神 加百利恩', '時械神ガブリオン', 'Effect Monster', 'Fairy', 'WATER', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。对方场上的卡全部回到持有者卡组。那之后，对方抽出回到自身卡组的数量。 ④：自己准备阶段发动。这张卡回到持有者卡组。'),
(10002346, 'Gachi Gachi Gantetsu', '硬邦邦岩铁', 'ガチガチガンテツ', 'XYZ Monster', 'Rock', 'EARTH', 2, 500, 1800, '2星怪兽×2 ①：只要这张卡在怪兽区域存在，自己场上的怪兽的攻击力·守备力上升这张卡的超量素材数量×200。 ②：这张卡被破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(36956512, 'Gadarla, the Mystery Dust Kaiju', '怪粉坏兽 伽达拉', '怪粉壊獣ガダーラ', 'Effect Monster', 'Insect', 'WIND', 8, 2700, 1600, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上攻击表示特殊召唤。 ②：对方场上有「坏兽」怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ③：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ④：1回合1次，把自己·对方场上3个坏兽指示物取除才能发动。这张卡以外的场上的全部怪兽的攻击力·守备力变成一半。这个效果在对方回合也能发动。');